# /// script
# requires-python = ">=3.11"
# dependencies = ["pyyaml>=6"]
# ///
"""Rebuild the generated files of a PhysicsHive workspace.

Writes INDEX.md (one line per card, artefact, paper and session, with each
claim's computed status, evidence, place in the draft and needs re-check flag)
and references.bib (one BibTeX entry per paper card, for the notes and the
draft, with keys made of the first author's name and the year). Both files are
git-ignored and never edited by hand, so running this twice gives identical
files.

Usage: uv run .physics-hive/scripts/regen.py [--root PATH] [--quiet]
"""

from __future__ import annotations

import argparse
import re
import sys
import unicodedata
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from cards import Workspace, find_root, natural_key  # noqa: E402
from human import one_line  # noqa: E402

HEADER = "<!-- Generated by .physics-hive/scripts/regen.py from the workspace files. Do not edit. -->"


def review_label(review) -> str:
    """Short name of a review: `R-S3-2`, with `by <user>` for a human verification."""
    label = review.id.split("_", 1)[1] if "_R-" in review.id else review.id
    if review.by_human:
        label += f" by {review.by.get('user', '?')}"
    return label


def evidence_parts(ws: Workspace, card_id: str) -> list[str]:
    parts = []
    for item in ws.evidence(card_id):
        reviews = "; ".join(f"{review_label(r)} {r.verdict}" for r in item.reviews) or "no review yet"
        parts.append(f"{item.artefact} [{reviews}]")
    return parts


def status_text(ws: Workspace, card_id: str) -> str:
    status = ws.status(card_id)
    if status == "refuted":
        return f"refuted by {', '.join(ws.refuters(card_id))}"
    if status == "revised":
        return f"revised by {', '.join(ws.revisers(card_id))}"
    return status


def recheck_text(ws: Workspace, card_id: str) -> str:
    causes = ws.needs_recheck(card_id)
    if not causes:
        return ""
    return "needs re-check (" + ", ".join(f"{c} {ws.status(c)}" for c in causes) + ")"


def card_line(ws: Workspace, card) -> str:
    fields = [f"**{card.id}**", status_text(ws, card.id)]
    place = ws.in_draft(card.id)
    if place == "conjecture" or (place == "result" and ws.status(card.id) != "established"):
        fields.append(f"in the draft as a {place}")
    recheck = recheck_text(ws, card.id)
    if recheck:
        fields.append(recheck)
    line = "- " + " · ".join(fields) + " — " + one_line(card.statement, 220)
    extras = []
    if card.kind == "claim":
        evidence = evidence_parts(ws, card.id)
        extras.append("evidence: " + (", ".join(evidence) if evidence else "none"))
    if card.refutes:
        extras.append("refutes " + ", ".join(card.refutes))
    if card.supersedes:
        extras.append("supersedes " + ", ".join(card.supersedes))
    if card.depends_on:
        extras.append("depends on " + ", ".join(card.depends_on))
    if card.produced_by.get("kind") == "human":
        extras.append(f"from {card.produced_by.get('user', '?')}")
    return line + ("" if not extras else " — " + " — ".join(extras))


def debrief_state(ws: Workspace, session) -> str:
    from human import read_by

    if session.debrief is None:
        return "no debrief yet"
    readers = read_by(ws.sessions.values())
    if session.id in readers:
        reader, date = readers[session.id]
        return f"debrief read by {reader}" + (f" on {date}" if date else "")
    return "debrief open"


def render_index(ws: Workspace) -> str:
    out = ["# Index", "", HEADER, ""]
    keys = bib_keys(ws)

    claims = ws.sorted_cards("claim")
    out += ["## Claims", ""]
    if claims:
        for status in ("established", "working", "revised", "refuted"):
            out += [card_line(ws, c) for c in claims if ws.status(c.id) == status]
    else:
        out.append("(none yet)")
    out.append("")

    out += ["## Dead ends", ""]
    out += [card_line(ws, c) for c in ws.sorted_cards("dead-end")] or ["(none yet)"]
    out.append("")

    out += ["## The draft", ""]
    if ws.draft:
        for block in ws.draft:
            title = f" ({one_line(block.title, 80)})" if block.title else ""
            named = ", ".join(f"{c} ({ws.status(c)})" for c in block.cards) or "no card named"
            out.append(f"- {block.kind.capitalize()}{title}, draft.tex line {block.line}: {named}")
    else:
        out.append("(no result or conjecture in draft.tex yet)")
    for flag in ws.draft_flags():
        out.append(f"- FLAG: {flag}")
    out.append("")

    out += ["## Artefacts", ""]
    if ws.artefacts:
        for art_id in sorted(ws.artefacts, key=natural_key):
            art = ws.artefacts[art_id]
            reviews = "; ".join(f"{review_label(r)} {r.verdict}" for r in ws.reviews_of(art_id)) or "no review yet"
            supports = ", ".join(art.supports) or "nothing"
            out.append(f"- **{art_id}** ({art.kind}, `{art.path}`) — supports {supports} — reviews: {reviews}")
    else:
        out.append("(none yet)")
    out.append("")

    out += ["## Literature", ""]
    if (ws.root / "literature" / "overview.md").is_file():
        out += ["Overview of the field: `literature/overview.md`.", ""]
    if ws.papers:
        for paper_id in sorted(ws.papers, key=natural_key):
            paper = ws.papers[paper_id]
            year = f" ({paper.year})" if paper.year else ""
            parts = [f"- **{paper_id}** [{keys[paper_id]}] — {one_line(paper.title, 160)}{year}"]
            rating = paper.rating or "?"
            mine = ws.ratings.get(paper_id)
            parts.append(f"rating {rating}" + (f", lead: {mine}" if mine else ""))
            if paper.topic:
                parts.append(f"topic: {one_line(paper.topic, 60)}")
            if paper.why:
                parts.append(one_line(paper.why, 200))
            out.append(" — ".join(parts))
    else:
        out.append("(no paper cards yet)")
    out.append("")

    out += ["## Sessions", ""]
    if ws.sessions:
        for session in sorted(ws.sessions.values(), key=lambda s: s.number):
            goal = one_line(session.goal, 160) or "(no brief yet)"
            note = f"note `{session.path}/note.tex`" if session.has_note else "no note yet"
            out.append(f"- **{session.id}** — {goal} — {note} — {debrief_state(ws, session)}")
    else:
        out.append("(no sessions yet)")
    out.append("")
    return "\n".join(out)


# ----- references.bib -----


def _ascii(text: str) -> str:
    return unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode()


def first_author_name(authors) -> str:
    """The family name of the first author, as letters for a BibTeX key ('Yang, Lei' or 'Lei Yang' -> 'yang')."""
    first = authors[0] if isinstance(authors, list) and authors else (authors or "")
    first = str(first).split(" and ")[0].strip()
    family = first.split(",")[0] if "," in first else (first.split()[-1] if first.split() else "")
    return re.sub(r"[^a-z]", "", _ascii(family).lower()) or "anon"


def bib_keys(ws: Workspace) -> dict[str, str]:
    """BibTeX key of each paper card: `yang2015`; when two papers share it, the one recorded first keeps it
    and the others get `b`, `c`, ... (so a key never changes once a note or the draft cites it)."""
    def order(paper):
        session = re.match(r"S(\d+)$", str(paper.meta.get("session") or ""))
        return (int(session.group(1)) if session else 10**9, natural_key(paper.id))

    keys: dict[str, str] = {}
    used: dict[str, int] = {}
    for paper in sorted(ws.papers.values(), key=order):
        year = re.sub(r"\D", "", str(paper.year or "")) or "nd"
        base = first_author_name(paper.meta.get("authors")) + year
        n = used.get(base, 0)
        keys[paper.id] = base if n == 0 else base + "bcdefghijklmnopqrstuvwxyz"[min(n - 1, 24)]
        used[base] = n + 1
    return keys


def render_bib(ws: Workspace) -> str:
    keys = bib_keys(ws)
    out = ["% Generated by .physics-hive/scripts/regen.py from the paper cards. Do not edit.", ""]
    for paper_id in sorted(ws.papers, key=lambda p: keys[p]):
        paper, meta = ws.papers[paper_id], ws.papers[paper_id].meta
        authors = meta.get("authors") or []
        authors = " and ".join(map(str, authors)) if isinstance(authors, list) else str(authors)
        fields = [("author", authors), ("title", "{" + paper.title + "}" if paper.title else ""),
                  ("journal", meta.get("journal")), ("year", paper.year), ("doi", meta.get("doi"))]
        arxiv = str(meta.get("arxiv") or "").strip()
        if arxiv:
            fields += [("eprint", arxiv), ("archivePrefix", "arXiv"), ("note", f"arXiv:{arxiv}")]
        fields.append(("paperid", paper_id))
        kind = "article" if meta.get("journal") else "misc"
        out.append(f"@{kind}{{{keys[paper_id]},")
        out += [f"  {name} = {{{value}}}," for name, value in fields if value not in (None, "")]
        out += ["}", ""]
    return "\n".join(out)


def regenerate(root: Path) -> Workspace:
    ws = Workspace(root)
    (root / "INDEX.md").write_text(render_index(ws), encoding="utf-8")
    (root / "references.bib").write_text(render_bib(ws), encoding="utf-8")
    return ws


def summary(ws: Workspace) -> str:
    claims = ws.sorted_cards("claim")
    counts: dict[str, int] = {}
    for card in claims:
        counts[ws.status(card.id)] = counts.get(ws.status(card.id), 0) + 1
    recheck = sum(1 for c in ws.cards if ws.needs_recheck(c))
    parts = [f"{n} {s}" for s, n in sorted(counts.items())]
    return (
        f"{len(claims)} claims ({', '.join(parts) or 'none'}), {len(ws.sorted_cards('dead-end'))} dead ends, "
        f"{recheck} cards needing a re-check, {len(ws.artefacts)} artefacts, {len(ws.papers)} paper cards"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", type=Path, help="workspace root (default: found from the current folder)")
    parser.add_argument("--quiet", action="store_true")
    args = parser.parse_args()
    root = args.root.resolve() if args.root else find_root()
    ws = regenerate(root)
    for problem in ws.problems:
        print(problem, file=sys.stderr)
    if not args.quiet:
        print(f"Wrote INDEX.md and references.bib: {summary(ws)}.")
        for flag in ws.draft_flags():
            print(f"Draft flag: {flag}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
